async function readJson(input: Request) {
  try { return await input.clone().json(); } catch { return undefined; }
}
export async function decode(input: Request, validator: any) {
 let query = {};
 let body = await readJson(input);
 let error;
 if (validator) {
  const queryMethod = input.method === 'GET';
  const originalQuery = query;
  const parsed = validator.safeParse(queryMethod ? query : body);
  if (!parsed.success) { error = () => invalid(parsed.error); }
  else if (queryMethod) { query = parsed.data; }
  else { body = parsed.data; }
 }
 return {body, error};
}

