import {z} from 'zod';
import {decode} from '../../parser';
import {persist} from '../../write';
export async function POST(request: Request) {
 const schema = z.object({title: z.string().optional(), caption: z.string().optional(), kind: z.enum(['note'])});
 const {body, error} = await decode(request, schema);
 if (error) { return error(); }
 const {title, caption} = body;
 const kind = body.kind;
 try {
  const saved = await persist('id', {title, caption, kind});
  return render(saved);
 } catch (issue) { return failed(issue); }
}
